#!/usr/bin/env bash
# xc.sh: build, run and debug an Xcode or Bazel app from VS Code without opening Xcode.
# Generated by setup-vscode-xcode.sh. Re-running the setup regenerates this file.
#
# Usage: .vscode/xcode/xc.sh <command>
#   build            Build the selected scheme (or Bazel target) for the selected simulator or macOS
#   run              Build, install, launch and stream the app's console output
#   test             Run the scheme's tests
#   clean            Clean build products and cached settings
#   debug-prepare    Build, launch paused, and hand off to the debugger (used by F5)
#   stop             Terminate the running app
#   logs             Follow the app's console output from the last debug session
#   select-scheme    Pick the scheme, or the Bazel app target (add --prompt to always ask)
#   select-sim       Pick the simulator (add --prompt to always ask)
#   refresh-index    Set up code completion (buildServer.json, or the Bazel build server)
#   open-sim         Boot the selected simulator and bring Simulator.app forward
#   info             Show the current configuration
set -eo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="$(cd "$HERE/../.." && pwd)"
CONFIG="$HERE/config.env"
STATE="$HERE/.state"
mkdir -p "$STATE"
cd "$ROOT"

XC_BUILD_SYSTEM="xcode"; XC_WORKSPACE=""; XC_PROJECT=""; XC_SCHEME=""; XC_CONFIGURATION="Debug"
XC_PLATFORM=""; XC_SIM_UDID=""; XC_SIM_NAME=""; XC_TARGET=""; XC_EXTRA_BUILD_ARGS=""
XC_BAZEL_TARGET=""; XC_BAZEL_TEST_TARGETS=""; XC_BAZEL_ARGS=""; XC_TEST_SCHEME=""
XC_VARS="XC_BUILD_SYSTEM XC_WORKSPACE XC_PROJECT XC_SCHEME XC_CONFIGURATION XC_PLATFORM XC_SIM_UDID XC_SIM_NAME XC_TARGET XC_EXTRA_BUILD_ARGS XC_BAZEL_TARGET XC_BAZEL_TEST_TARGETS XC_BAZEL_ARGS XC_TEST_SCHEME"
# shellcheck source=/dev/null
if [ -f "$CONFIG" ]; then . "$CONFIG"; fi

if [ -t 1 ]; then
  B=$'\033[1m'; R=$'\033[31m'; G=$'\033[32m'; Y=$'\033[33m'; C=$'\033[36m'; N=$'\033[0m'
else
  B=""; R=""; G=""; Y=""; C=""; N=""
fi
info() { printf '%s▸%s %s\n' "$C" "$N" "$*"; }
ok()   { printf '%s✔%s %s\n' "$G" "$N" "$*"; }
warn() { printf '%s! %s%s\n' "$Y" "$*" "$N" >&2; }
die()  { printf '%s✖ %s%s\n' "$R" "$*" "$N" >&2; exit 1; }

interactive() { [ -t 0 ] && [ "${XC_AUTO:-0}" != 1 ]; }

# choose <default-index> <question> <items...>; sets CHOICE to the picked index.
choose() {
  local def="$1" question="$2" i=0 item ans
  shift 2
  echo "$question"
  for item in "$@"; do
    if [ "$i" -eq "$def" ]; then
      printf '  %s%2d) %s  (default)%s\n' "$B" $((i + 1)) "$item" "$N"
    else
      printf '  %2d) %s\n' $((i + 1)) "$item"
    fi
    i=$((i + 1))
  done
  while :; do
    read -r -p "Choose 1-$# (Enter = $((def + 1))): " ans || ans=""
    if [ -z "$ans" ]; then CHOICE=$def; return 0; fi
    case "$ans" in
      *[!0-9]*) ;;
      *) if [ "$ans" -ge 1 ] && [ "$ans" -le $# ]; then CHOICE=$((ans - 1)); return 0; fi ;;
    esac
    echo "Please type a number from 1 to $#."
  done
}

save_config() {
  local v
  {
    echo "# Used by .vscode/xcode/xc.sh. Change with the 'Xcode: Select Scheme' (or 'Xcode: Select"
    echo "# Bazel Target') and 'Xcode: Select Simulator' tasks, or edit by hand."
    echo "# XC_TARGET: app target to launch when a scheme builds several apps (optional)."
    echo "# XC_EXTRA_BUILD_ARGS: extra xcodebuild arguments, e.g. \"-quiet\" (optional)."
    echo "# XC_TEST_SCHEME: scheme for 'Xcode: Test' when tests live in their own scheme (optional)."
    echo "# XC_BAZEL_TEST_TARGETS: Bazel test targets for 'Xcode: Test' (default: every *_unit_test/*_ui_test)."
    echo "# XC_BAZEL_ARGS: extra Bazel flags for build/test, e.g. \"--config=sim\" (optional)."
    for v in $XC_VARS; do
      printf '%s=%q\n' "$v" "${!v}"
    done
  } > "$CONFIG"
  rm -f "$STATE/settings.env"
}

container_args() {
  if [ -n "$XC_WORKSPACE" ]; then CARGS=(-workspace "$XC_WORKSPACE")
  elif [ -n "$XC_PROJECT" ]; then CARGS=(-project "$XC_PROJECT")
  else die "No .xcworkspace or .xcodeproj configured. Re-run setup-vscode-xcode.sh."
  fi
}

sim_family() {
  case "$XC_PLATFORM" in
    ios) echo iOS ;; tvos) echo tvOS ;; watchos) echo watchOS ;; visionos) echo xrOS ;; *) echo "" ;;
  esac
}
download_name() {
  case "$XC_PLATFORM" in
    ios) echo iOS ;; tvos) echo tvOS ;; watchos) echo watchOS ;; visionos) echo visionOS ;;
  esac
}
is_sim() { [ -n "$(sim_family)" ]; }
# A simulator build can't run as a Mac process: launched that way it stops with SIGSTOP and dies.
# This happens when XC_PLATFORM says macOS but the scheme's app is an iOS/tvOS/watchOS/visionOS one.
check_host_app() {
  case "$EXEC_PATH" in
    *simulator/*|*-iphoneos/*|*-appletvos/*|*-watchos/*|*-xros/*)
      die "$PRODUCT_NAME is built for a simulator or device ($EXEC_PATH), but XC_PLATFORM is '$XC_PLATFORM', so it would be started as a Mac process and crash. Run the task 'Xcode: Select Scheme' to detect the platform again, or set XC_PLATFORM (e.g. ios) in .vscode/xcode/config.env." ;;
  esac
}
is_bazel() { [ "$XC_BUILD_SYSTEM" = bazel ]; }
dest_label() { if is_sim; then echo "$XC_SIM_NAME"; else echo "macOS"; fi; }
re_escape() { printf '%s' "$1" | sed 's/[][\.*^$+?(){}|]/\\&/g'; }

# Force the terminal renderer: on CI, xcbeautify would otherwise switch to GitHub annotations.
pretty() {
  if command -v xcbeautify >/dev/null 2>&1; then xcbeautify --renderer terminal --disable-colored-output; else cat; fi
}

# Picks the app target from `xcodebuild -showBuildSettings -json` and prints shell assignments.
PY_PICK='
import json, shlex, sys
want = sys.argv[1] if len(sys.argv) > 1 else ""
try:
    data = json.load(sys.stdin)
except ValueError:
    sys.exit(1)
if not data:
    sys.exit(1)
def matches(t):
    if want:
        return t.get("target") == want
    return t.get("buildSettings", {}).get("WRAPPER_EXTENSION") == "app"
pick = next((t for t in data if matches(t)), data[0])
s = pick.get("buildSettings", {})
d = s.get("TARGET_BUILD_DIR", "")
vals = {
    "APP_PATH": d + "/" + s.get("FULL_PRODUCT_NAME", ""),
    "EXEC_PATH": d + "/" + s.get("EXECUTABLE_PATH", ""),
    "BUNDLE_ID": s.get("PRODUCT_BUNDLE_IDENTIFIER", ""),
    "PRODUCT_NAME": s.get("FULL_PRODUCT_NAME", ""),
    "TARGET_NAME": pick.get("target", ""),
    "SUPPORTED_PLATFORMS": s.get("SUPPORTED_PLATFORMS", ""),
    # Projects generated by rules_xcodeproj point the debugger at an lldbinit (working directory and
    # source maps for Bazel-built code). Xcode writes it in a Run pre-action, so keep what is needed
    # to write it ourselves.
    "LLDB_INIT": s.get("BAZEL_LLDB_INIT", ""),
    "LLDB_INIT_CMD": "",
}
script = s.get("BAZEL_INTEGRATION_DIR", "") + "/create_lldbinit.sh"
if vals["LLDB_INIT"] and s.get("BAZEL_INTEGRATION_DIR"):
    keys = ["PROJECT_DIR", "BAZEL_OUT", "BAZEL_EXTERNAL", "OBJROOT", "CONFIGURATION", "BAZEL_LLDB_INIT",
            "RESOLVED_REPOSITORIES", "BAZEL_SEPARATE_INDEXBUILD_OUTPUT_BASE"]
    vals["LLDB_INIT_CMD"] = " ".join(["env"] + ["%s=%s" % (k, shlex.quote(s.get(k, ""))) for k in keys]
                                     + ["/bin/bash", shlex.quote(script)])
for k in sorted(vals):
    print("%s=%s" % (k, shlex.quote(vals[k])))
'

PY_SCHEMES='
import json, sys
d = json.load(sys.stdin)
o = d.get("workspace") or d.get("project") or {}
for s in o.get("schemes", []):
    print(s)
'

# Lists available simulators of one family. First line: "<default index>\t<exact match 0|1>",
# then one "<udid>\t<label>\t<name>" line per simulator, newest runtime first.
# Runs a command in a pseudo-terminal and copies its output, unbuffered, to a file ("-" = stdout).
# simctl holds its output back when writing to a file or pipe; a terminal makes it stream.
PY_PTY='
import os, pty, sys
out = sys.stdout.buffer if sys.argv[1] == "-" else open(sys.argv[1], "ab", buffering=0)
pid, fd = pty.fork()
if pid == 0:
    os.execvp(sys.argv[2], sys.argv[2:])
while True:
    try:
        data = os.read(fd, 4096)
    except OSError:
        break
    if not data:
        break
    out.write(data)
    out.flush()
_, status = os.waitpid(pid, 0)
sys.exit(os.WEXITSTATUS(status) if os.WIFEXITED(status) else 1)
'
run_in_pty() { local dest="$1"; shift; python3 -I -c "$PY_PTY" "$dest" "$@"; }

PY_SIMS='
import json, re, sys
fam, pref, cur_udid, cur_name = (sys.argv[1:] + ["", "", "", ""])[:4]
devices = json.load(sys.stdin).get("devices", {})
rows = []
for rt, devs in devices.items():
    m = re.search(r"SimRuntime\.%s-(\d+)-(\d+)(?:-(\d+))?$" % re.escape(fam), rt)
    if not m:
        continue
    ver = tuple(int(x or 0) for x in m.groups())
    label_ver = "%d.%d" % ver[:2] + (".%d" % ver[2] if ver[2] else "")
    for d in devs:
        if d.get("isAvailable", True) is False:
            continue
        rows.append({"ver": ver, "name": d["name"], "udid": d["udid"], "state": d.get("state", ""),
                     "label": "%s (%s %s)%s" % (d["name"], fam.replace("xrOS", "visionOS"), label_ver,
                                                 ", booted" if d.get("state") == "Booted" else "")})
if not rows:
    sys.exit(0)
rows.sort(key=lambda r: r["ver"], reverse=True)
def newest(pred):
    for i, r in enumerate(rows):
        if pred(r):
            return i
    return None
exact = 0
idx = None
if pref:
    idx = newest(lambda r: r["name"] == pref or r["udid"] == pref)
elif cur_udid:
    idx = newest(lambda r: r["udid"] == cur_udid)
    if idx is None and cur_name:
        idx = newest(lambda r: r["name"] == cur_name)
if idx is not None:
    exact = 1
else:
    def score(r):
        s = 0
        if r["state"] == "Booted":
            s += 1000
        if fam == "iOS":
            m = re.match(r"iPhone (\d+)( Pro)?$", r["name"])
            if m:
                s += 100 + int(m.group(1)) + (5 if m.group(2) else 0)
            elif r["name"].startswith("iPhone"):
                s += 50
        return (s, r["ver"])
    idx = max(range(len(rows)), key=lambda i: score(rows[i]))
print("%d\t%d" % (idx, exact))
for r in rows:
    print("%s\t%s\t%s" % (r["udid"], r["label"], r["name"]))
'

detect_platform() {
  container_args
  info "Detecting the platform of scheme '$XC_SCHEME'..."
  # shellcheck disable=SC2034  # set by eval
  local SUPPORTED_PLATFORMS="" APP_PATH EXEC_PATH BUNDLE_ID PRODUCT_NAME TARGET_NAME assignments
  assignments="$(xcodebuild "${CARGS[@]}" -scheme "$XC_SCHEME" -showBuildSettings -json 2>/dev/null | python3 -I -c "$PY_PICK" "$XC_TARGET")" || assignments=""
  eval "$assignments"
  case " $SUPPORTED_PLATFORMS " in
    *" iphonesimulator "*) XC_PLATFORM=ios ;;
    *" xrsimulator "*) XC_PLATFORM=visionos ;;
    *" appletvsimulator "*) XC_PLATFORM=tvos ;;
    *" watchsimulator "*) XC_PLATFORM=watchos ;;
    *" macosx "*) XC_PLATFORM=macos ;;
    *) warn "Couldn't detect the platform (got '$SUPPORTED_PLATFORMS'); assuming iOS."; XC_PLATFORM=ios ;;
  esac
}

ensure_sim() {
  is_sim || return 0
  if [ -n "$XC_SIM_UDID" ] && xcrun simctl list devices available 2>/dev/null | grep -q "$XC_SIM_UDID"; then
    return 0
  fi
  [ -z "$XC_SIM_UDID" ] || warn "Simulator '$XC_SIM_NAME' is no longer installed; picking another one."
  XC_AUTO=1 cmd_select_sim
}

build_args() {
  if is_bazel; then bazel_args; return 0; fi
  container_args
  [ -n "$XC_SCHEME" ] || die "No scheme selected. Run the task 'Xcode: Select Scheme'."
  if [ -z "$XC_PLATFORM" ]; then detect_platform; save_config; fi
  ensure_sim
  local dest
  if is_sim; then dest="id=$XC_SIM_UDID"; else dest="platform=macOS,arch=$(uname -m)"; fi
  BARGS=("${CARGS[@]}" -scheme "$XC_SCHEME" -configuration "$XC_CONFIGURATION" -destination "$dest")
}

# Resolves APP_PATH, EXEC_PATH, BUNDLE_ID, PRODUCT_NAME for the current build (cached).
load_settings() {
  if is_bazel; then bazel_load_settings; return 0; fi
  local cache="$STATE/settings.env" key assignments
  key="# v2|$(printf '%s|' "${BARGS[@]}" "$XC_TARGET")"
  if [ -f "$cache" ] && [ "$(head -n 1 "$cache")" = "$key" ]; then
    # shellcheck source=/dev/null
    . "$cache"
    return 0
  fi
  assignments="$(xcodebuild "${BARGS[@]}" -showBuildSettings -json 2>/dev/null | python3 -I -c "$PY_PICK" "$XC_TARGET")" \
    || die "Couldn't read build settings for scheme '$XC_SCHEME'."
  printf '%s\n%s\n' "$key" "$assignments" > "$cache"
  eval "$assignments"
}

boot_sim() {
  info "Booting $XC_SIM_NAME..."
  xcrun simctl bootstatus "$XC_SIM_UDID" -b >/dev/null 2>&1 \
    || die "Couldn't boot simulator '$XC_SIM_NAME' ($XC_SIM_UDID)."
  open "$(xcode-select -p)/Applications/Simulator.app" >/dev/null 2>&1 || open -a Simulator >/dev/null 2>&1 || true
}

install_app() {
  [ -d "$APP_PATH" ] || die "Built app not found at $APP_PATH. Set XC_TARGET in .vscode/xcode/config.env if the scheme builds several apps."
  info "Installing $PRODUCT_NAME on $XC_SIM_NAME..."
  xcrun simctl install "$XC_SIM_UDID" "$APP_PATH" || die "Install failed."
}

cmd_build() {
  if is_bazel; then bazel_build; return 0; fi
  build_args
  info "Building ${B}$XC_SCHEME${N} ($XC_CONFIGURATION) for $(dest_label)..."
  local t0=$SECONDS
  # shellcheck disable=SC2086
  if xcodebuild "${BARGS[@]}" -skipMacroValidation -skipPackagePluginValidation $XC_EXTRA_BUILD_ARGS build 2>&1 | pretty; then
    ok "Build succeeded in $((SECONDS - t0))s."
  else
    die "Build failed. Errors are listed in the Problems panel (Shift+Cmd+M)."
  fi
}

cmd_run() {
  cmd_build
  load_settings
  if ! is_sim; then
    check_host_app
    pkill -f -- "$(re_escape "$EXEC_PATH")" 2>/dev/null || true
    info "Running $PRODUCT_NAME (stop with Ctrl+C or the 'Xcode: Stop App' task)."
    exec "$EXEC_PATH"
  fi
  boot_sim
  install_app
  info "Launching $BUNDLE_ID. App output follows; Ctrl+C or 'Xcode: Stop App' stops it."
  if [ -t 1 ]; then
    exec xcrun simctl launch --console-pty --terminate-running-process "$XC_SIM_UDID" "$BUNDLE_ID"
  fi
  run_in_pty - xcrun simctl launch --console-pty --terminate-running-process "$XC_SIM_UDID" "$BUNDLE_ID"
}

BG_PIDS=""
# shellcheck disable=SC2086  # BG_PIDS is a space-separated pid list
stop_bg() { if [ -n "$BG_PIDS" ]; then kill $BG_PIDS 2>/dev/null || true; BG_PIDS=""; fi; }

cmd_debug_prepare() {
  echo "XC_DEBUG_PREPARE_BEGIN"
  # Until this run gets the app ready, F5 (including "Debug Anyway" after a failed prepare) must not
  # reuse the commands of an earlier run, which could launch a stale or wrong binary.
  printf '%s\n' 'script print("error: Xcode: Prepare Debug did not finish, so there is nothing to debug. See its terminal, fix the error and press F5 again.")' \
    > "$STATE/process.lldb"
  : > "$STATE/target.lldb"
  cmd_build
  load_settings
  local line="" pid="" i launcher
  rm -f "$STATE/app.pid"
  {
    printf 'target create "%s"\n' "$EXEC_PATH"
    if is_bazel; then
      bazel_lldb_settings
    elif [ -n "${LLDB_INIT:-}" ]; then
      if [ -n "${LLDB_INIT_CMD:-}" ]; then
        mkdir -p "$(dirname "$LLDB_INIT")"
        eval "$LLDB_INIT_CMD" >&2 || warn "Couldn't write the rules_xcodeproj lldbinit; breakpoints may not resolve."
      fi
      # Skip its swift_debug_settings.py import: that stop hook kept the app from ever reaching
      # a breakpoint when attaching from outside Xcode. The paths and source maps are what matter.
      if [ -f "$LLDB_INIT" ]; then
        grep -v '^command script import' "$LLDB_INIT" > "$STATE/bazel.lldbinit" || true
        printf 'command source -s 1 -e 0 "%s"\n' "$STATE/bazel.lldbinit"
      fi
    fi
  } > "$STATE/target.lldb"
  if ! is_sim; then
    check_host_app
    # LLDB launches the app itself; its output shows in VS Code's Debug Console.
    pkill -f -- "$(re_escape "$EXEC_PATH")" 2>/dev/null || true
    printf 'process launch\n' > "$STATE/process.lldb"
    ok "Ready. Launching under the debugger; app output appears in the Debug Console."
    echo "XC_DEBUG_READY"
    return 0
  fi

  boot_sim
  install_app
  info "Launching $BUNDLE_ID paused, waiting for the debugger..."
  # --console-pty gives the app a terminal, so print() output isn't held back by buffering.
  : > "$STATE/console.log"
  trap stop_bg EXIT INT TERM HUP
  run_in_pty "$STATE/console.log" xcrun simctl launch --console-pty --wait-for-debugger \
    --terminate-running-process "$XC_SIM_UDID" "$BUNDLE_ID" </dev/null >/dev/null 2>&1 &
  launcher=$!
  BG_PIDS="$launcher"
  for i in $(seq 1 120); do
    line="$(grep -m 1 -E "^$(re_escape "$BUNDLE_ID"): [0-9]+" "$STATE/console.log" 2>/dev/null || true)"
    [ -n "$line" ] && break
    kill -0 "$launcher" 2>/dev/null || die "Launch failed: $(cat "$STATE/console.log")"
    sleep 0.25
  done
  pid="${line##*: }"
  pid="${pid%%[!0-9]*}"
  [ -n "$pid" ] || die "Couldn't read the app's process id. simctl said: $(cat "$STATE/console.log")"
  echo "$pid" > "$STATE/app.pid"
  printf 'process attach --pid %s\n' "$pid" > "$STATE/process.lldb"
  ok "Ready. Attaching the debugger to process $pid..."
  echo "XC_DEBUG_READY"
  echo "──────── app output ────────"
  tail -n +2 -f "$STATE/console.log" &
  BG_PIDS="$BG_PIDS $!"
  while kill -0 "$pid" 2>/dev/null; do sleep 1; done
  sleep 0.5
  stop_bg
  echo "──────── app exited ────────"
}

cmd_stop() {
  build_args
  load_settings
  if is_sim; then
    xcrun simctl terminate "$XC_SIM_UDID" "$BUNDLE_ID" >/dev/null 2>&1 || true
  else
    pkill -f -- "$(re_escape "$EXEC_PATH")" 2>/dev/null || true
  fi
  ok "Stopped $PRODUCT_NAME."
}

cmd_test() {
  if is_bazel; then bazel_test; return 0; fi
  build_args
  local scheme="${XC_TEST_SCHEME:-$XC_SCHEME}" log="$STATE/test.log" i
  for i in 1 2; do
    info "Testing ${B}$scheme${N} on $(dest_label)..."
    BARGS=("${CARGS[@]}" -scheme "$scheme" "${BARGS[@]:${#CARGS[@]}+2}")
    # shellcheck disable=SC2086
    if xcodebuild "${BARGS[@]}" -skipMacroValidation -skipPackagePluginValidation $XC_EXTRA_BUILD_ARGS test 2>&1 \
        | tee "$log" | pretty; then
      ok "Tests passed."
      return 0
    fi
    # Projects often keep tests in their own scheme (rules_xcodeproj makes "App" and "AppTests").
    if [ "$i" = 1 ] && [ -z "${XC_TEST_SCHEME:-}" ] && grep -q "not currently configured for the test action" "$log" \
        && xcodebuild "${CARGS[@]}" -list 2>/dev/null | grep -qx "[[:space:]]*${XC_SCHEME}Tests"; then
      warn "Scheme '$XC_SCHEME' has no tests; using '${XC_SCHEME}Tests' (set XC_TEST_SCHEME in .vscode/xcode/config.env to choose)."
      scheme="${XC_SCHEME}Tests"
      continue
    fi
    break
  done
  die "Tests failed (or the scheme has no test action; set XC_TEST_SCHEME in .vscode/xcode/config.env)."
}

cmd_clean() {
  if is_bazel; then
    bazel_cmd clean
    rm -rf "$STATE"
    ok "Cleaned."
    return 0
  fi
  build_args
  xcodebuild "${BARGS[@]}" clean 2>&1 | pretty
  rm -rf "$STATE"
  ok "Cleaned."
}

cmd_select_scheme() {
  local force=0 list s i def=-1 found=0 base want new old_platform
  [ "$1" = "--prompt" ] && force=1
  if is_bazel; then bazel_select_target "$@"; return 0; fi
  container_args
  info "Reading schemes from ${XC_WORKSPACE:-$XC_PROJECT}..."
  list="$(xcodebuild "${CARGS[@]}" -list -json 2>/dev/null | python3 -I -c "$PY_SCHEMES")" \
    || die "Couldn't list schemes. Try running: xcodebuild ${CARGS[*]} -list"
  local schemes=()
  while IFS= read -r s; do [ -n "$s" ] && schemes+=("$s"); done <<< "$list"
  [ ${#schemes[@]} -gt 0 ] || die "No schemes found in ${XC_WORKSPACE:-$XC_PROJECT}."

  base="$(basename "${XC_WORKSPACE:-$XC_PROJECT}")"; base="${base%.*}"
  for i in "${!schemes[@]}"; do [ "${schemes[$i]}" = "$base" ] && def=$i; done
  if [ "$def" -lt 0 ]; then
    for i in "${!schemes[@]}"; do
      case "${schemes[$i]}" in Pods-*) ;; *) def=$i; break ;; esac
    done
  fi
  [ "$def" -ge 0 ] || def=0
  want="${XC_PREF_SCHEME:-$XC_SCHEME}"
  if [ -n "$want" ]; then
    for i in "${!schemes[@]}"; do
      if [ "${schemes[$i]}" = "$want" ]; then def=$i; found=1; fi
    done
    [ "$found" = 1 ] || warn "Scheme '$want' not found."
  fi
  if [ ${#schemes[@]} -gt 1 ] && interactive; then
    # Ask when forced, or when nothing obviously matches the project name.
    if [ "$force" = 1 ] || { [ "$found" = 0 ] && [ "${schemes[$def]}" != "$base" ]; }; then
      choose "$def" "Which scheme should VS Code build?" "${schemes[@]}"
      def=$CHOICE
    fi
  fi
  new="${schemes[$def]}"
  XC_SCHEME="$new"
  ok "Scheme: $XC_SCHEME"
  old_platform="$XC_PLATFORM"
  detect_platform
  ok "Platform: $XC_PLATFORM"
  [ "$old_platform" = "$XC_PLATFORM" ] || { XC_SIM_UDID=""; XC_SIM_NAME=""; }
  save_config
  if is_sim && [ -z "$XC_SIM_UDID" ]; then cmd_select_sim; fi
  cmd_refresh_index
}

cmd_select_sim() {
  local force=0 rows fam first=1 a b c def=0 exact=0
  [ "$1" = "--prompt" ] && force=1
  if [ -z "$XC_PLATFORM" ] && [ -n "$XC_SCHEME" ] && ! is_bazel; then detect_platform; fi
  if ! is_sim; then ok "This scheme runs on macOS, so no simulator is needed."; return 0; fi
  fam="$(sim_family)"
  rows="$(xcrun simctl list devices available -j 2>/dev/null \
    | python3 -I -c "$PY_SIMS" "$fam" "${XC_PREF_SIM:-}" "$XC_SIM_UDID" "$XC_SIM_NAME")" || rows=""
  if [ -z "$rows" ]; then
    warn "No $(download_name) simulators are installed."
    if interactive; then
      read -r -p "Download the $(download_name) simulator runtime now (several GB)? [Y/n] " a || a=""
      case "$a" in n|N*) die "Install one with: xcodebuild -downloadPlatform $(download_name)" ;; esac
      xcodebuild -downloadPlatform "$(download_name)" || die "Download failed."
      rows="$(xcrun simctl list devices available -j 2>/dev/null \
        | python3 -I -c "$PY_SIMS" "$fam" "${XC_PREF_SIM:-}" "$XC_SIM_UDID" "$XC_SIM_NAME")" || rows=""
    fi
    [ -n "$rows" ] || die "Install a runtime with: xcodebuild -downloadPlatform $(download_name)"
  fi
  local udids=() labels=() names=()
  while IFS=$'\t' read -r a b c; do
    if [ "$first" = 1 ]; then def="$a"; exact="$b"; first=0; continue; fi
    udids+=("$a"); labels+=("$b"); names+=("$c")
  done <<< "$rows"
  [ -z "${XC_PREF_SIM:-}" ] || [ "$exact" = 1 ] || warn "Simulator '$XC_PREF_SIM' not found."
  if [ "$force" = 1 ] && [ ${#udids[@]} -gt 1 ] && interactive; then
    choose "$def" "Which simulator should apps run on?" "${labels[@]}"
    def=$CHOICE
  fi
  XC_SIM_UDID="${udids[$def]}"
  XC_SIM_NAME="${names[$def]}"
  save_config
  ok "Simulator: ${labels[$def]}"
}

cmd_refresh_index() {
  if is_bazel; then bazel_refresh_index; return 0; fi
  container_args
  [ -n "$XC_SCHEME" ] || die "No scheme selected."
  if ! command -v xcode-build-server >/dev/null 2>&1; then
    warn "xcode-build-server isn't installed (brew install xcode-build-server); code completion won't see your Xcode project."
    return 0
  fi
  if xcode-build-server config "${CARGS[@]}" -scheme "$XC_SCHEME" >/dev/null 2>&1; then
    ok "Code completion set up for '$XC_SCHEME' (buildServer.json). After a build, run 'Swift: Restart LSP Server' if completions look stale."
  else
    warn "xcode-build-server config failed; code completion may be limited."
  fi
}

cmd_info() {
  build_args
  load_settings
  if is_bazel; then
    echo "Build system:  Bazel ($(bazel_bin))"
    echo "Target:        $XC_BAZEL_TARGET (-c $(bazel_mode))"
  else
    echo "Container:     ${XC_WORKSPACE:-$XC_PROJECT}"
    echo "Scheme:        $XC_SCHEME ($XC_CONFIGURATION)"
  fi
  echo "Destination:   $(dest_label) ${XC_SIM_UDID:+($XC_SIM_UDID)}"
  echo "App:           $APP_PATH"
  echo "Bundle id:     $BUNDLE_ID"
}

# ── Bazel (rules_apple) ────────────────────────────────────────────────────────
# With XC_BUILD_SYSTEM=bazel, the app is built with `bazel build` directly (no .xcodeproj),
# then the .ipa/.zip is unpacked into .vscode/xcode/.state/app and installed like any other app.

bazel_bin() {
  if command -v bazel >/dev/null 2>&1; then echo bazel
  elif command -v bazelisk >/dev/null 2>&1; then echo bazelisk
  else die "Bazel isn't installed. Install it with: brew install bazelisk"
  fi
}
# UI flags only: they don't change Bazel's analysis cache. Plain output keeps the Problems matcher happy.
bazel_cmd() { local sub="$1"; shift; "$(bazel_bin)" "$sub" --color=no --curses=no "$@"; }

bazel_mode() {
  case "$XC_CONFIGURATION" in
    Release|release|opt) echo opt ;;
    fastbuild) echo fastbuild ;;
    *) echo dbg ;;
  esac
}

# Sets BFLAGS: compilation mode plus the CPU flags that make rules_apple build for the simulator.
bazel_flags() {
  local arch sim
  arch="$(uname -m)"
  if [ "$arch" = arm64 ]; then sim=sim_arm64; else arch=x86_64; sim=x86_64; fi
  BFLAGS=("--compilation_mode=$(bazel_mode)")
  case "$XC_PLATFORM" in
    ios) BFLAGS+=("--ios_multi_cpus=$sim") ;;
    tvos) BFLAGS+=("--tvos_cpus=$sim") ;;
    watchos) BFLAGS+=("--watchos_cpus=$arch") ;;
    visionos) BFLAGS+=("--visionos_cpus=sim_arm64") ;;
    macos) BFLAGS+=("--macos_cpus=$arch") ;;
  esac
  # shellcheck disable=SC2206  # XC_BAZEL_ARGS is a space-separated flag list
  [ -z "$XC_BAZEL_ARGS" ] || BFLAGS+=($XC_BAZEL_ARGS)
}

bazel_args() {
  [ -n "$XC_BAZEL_TARGET" ] || die "No Bazel target selected. Run the task 'Xcode: Select Bazel Target'."
  [ -n "$XC_PLATFORM" ] || bazel_select_target
  ensure_sim
  bazel_flags
  BARGS=("$XC_BAZEL_TARGET")
}

# Caches `bazel info` paths the debugger needs (they only change if the output base moves).
bazel_info() {
  local cache="$STATE/bazel-info.env" ws
  if [ -f "$cache" ]; then
    # shellcheck source=/dev/null
    . "$cache"
    [ "${BZ_ROOT:-}" = "$ROOT" ] && [ -d "${BZ_EXECROOT:-/nonexistent}" ] && return 0
  fi
  ws="$(bazel_cmd info --noshow_progress execution_root output_base 2>/dev/null)" || die "bazel info failed."
  BZ_EXECROOT="$(printf '%s\n' "$ws" | sed -n 's/^execution_root: //p')"
  BZ_OUTPUT_BASE="$(printf '%s\n' "$ws" | sed -n 's/^output_base: //p')"
  BZ_ROOT="$ROOT"
  printf 'BZ_EXECROOT=%q\nBZ_OUTPUT_BASE=%q\nBZ_ROOT=%q\n' "$BZ_EXECROOT" "$BZ_OUTPUT_BASE" "$BZ_ROOT" > "$cache"
}

plist_get() { plutil -extract "$2" raw -o - "$1" 2>/dev/null; }

# Finds the target's .ipa/.zip/.app, unpacks it into $STATE/app and sets APP_PATH, EXEC_PATH, BUNDLE_ID...
bazel_stage_app() {
  local out f line stamp plist exe
  out="$(bazel_cmd cquery --noshow_progress "${BFLAGS[@]}" --output=files "$XC_BAZEL_TARGET" 2>"$STATE/cquery.err")" \
    || die "bazel cquery failed: $(tail -n 20 "$STATE/cquery.err")"
  f=""
  while IFS= read -r line; do
    case "$line" in *.ipa|*.app|*.zip) f="$line"; break ;; esac
  done <<< "$out"
  [ -n "$f" ] || die "$XC_BAZEL_TARGET doesn't produce an .ipa, .zip or .app (outputs: $out). Is it an *_application target?"
  case "$f" in /*) ;; *) bazel_info; f="$BZ_EXECROOT/$f" ;; esac
  [ -e "$f" ] || die "$f doesn't exist yet. Build first (Shift+Cmd+B)."
  if [ -d "$f" ]; then
    APP_PATH="$f"
  else
    stamp="$f $(stat -f '%m %z' "$f" 2>/dev/null || stat -c '%Y %s' "$f")"
    if [ "$(cat "$STATE/app.stamp" 2>/dev/null)" != "$stamp" ] || [ -z "$(find "$STATE/app" -maxdepth 2 -name '*.app' -type d 2>/dev/null)" ]; then
      rm -rf "$STATE/app"
      mkdir -p "$STATE/app"
      unzip -q -o "$f" -d "$STATE/app" || die "Couldn't unpack $f."
      chmod -R u+w "$STATE/app"
      printf '%s' "$stamp" > "$STATE/app.stamp"
    fi
    APP_PATH="$(find "$STATE/app" -maxdepth 2 -name '*.app' -type d | head -n 1)"
    [ -n "$APP_PATH" ] || die "No .app inside $f."
  fi
  if [ -f "$APP_PATH/Contents/Info.plist" ]; then
    plist="$APP_PATH/Contents/Info.plist"; exe="$(plist_get "$plist" CFBundleExecutable)"
    EXEC_PATH="$APP_PATH/Contents/MacOS/$exe"
  else
    plist="$APP_PATH/Info.plist"; exe="$(plist_get "$plist" CFBundleExecutable)"
    EXEC_PATH="$APP_PATH/$exe"
  fi
  BUNDLE_ID="$(plist_get "$plist" CFBundleIdentifier)"
  PRODUCT_NAME="$(basename "$APP_PATH")"
  # shellcheck disable=SC2034  # written out via ${!v}
  TARGET_NAME="$XC_BAZEL_TARGET"
  [ -n "$exe" ] && [ -n "$BUNDLE_ID" ] || die "Couldn't read CFBundleExecutable/CFBundleIdentifier from $plist."
  {
    echo "# bazel|$XC_BAZEL_TARGET|${BFLAGS[*]}"
    for v in APP_PATH EXEC_PATH BUNDLE_ID PRODUCT_NAME TARGET_NAME; do printf '%s=%q\n' "$v" "${!v}"; done
  } > "$STATE/settings.env"
}

bazel_load_settings() {
  local cache="$STATE/settings.env"
  if [ -f "$cache" ] && [ "$(head -n 1 "$cache")" = "# bazel|$XC_BAZEL_TARGET|${BFLAGS[*]}" ]; then
    # shellcheck source=/dev/null
    . "$cache"
    return 0
  fi
  bazel_stage_app
}

bazel_build() {
  bazel_args
  info "Building ${B}$XC_BAZEL_TARGET${N} with Bazel (-c $(bazel_mode)) for $(dest_label)..."
  local t0=$SECONDS
  if bazel_cmd build "${BFLAGS[@]}" "$XC_BAZEL_TARGET" 2>&1; then
    bazel_stage_app
    ok "Build succeeded in $((SECONDS - t0))s."
  else
    die "Build failed. Errors are listed in the Problems panel (Shift+Cmd+M)."
  fi
}

TEST_KINDS='kind("(ios|macos|tvos|watchos|visionos)_(unit|ui)_test", //...)'

bazel_test() {
  bazel_args
  local targets="$XC_BAZEL_TEST_TARGETS"
  if [ -z "$targets" ]; then
    targets="$(bazel_cmd query --keep_going --noshow_progress "$TEST_KINDS" 2>/dev/null | tr '\n' ' ')" || true
    [ -n "${targets// /}" ] || die "No *_unit_test or *_ui_test targets found. Set XC_BAZEL_TEST_TARGETS in .vscode/xcode/config.env."
  fi
  info "Testing ${B}$targets${N}with Bazel..."
  info "The first run creates and boots a BAZEL_TEST simulator, which can take a few minutes; later runs reuse it."
  # The longer timeout covers that first boot; XC_BAZEL_ARGS (in BFLAGS, later on the line) can override it.
  # shellcheck disable=SC2086  # targets is a space-separated label list
  if bazel_cmd test --test_timeout=900 --test_output=errors "${BFLAGS[@]}" $targets 2>&1; then
    ok "Tests passed."
  else
    die "Tests failed."
  fi
}

APP_KINDS='kind("(ios|macos|tvos|watchos|visionos)_application", //...)'

bazel_select_target() {
  local force=0 out kind rule label i def=0 found=0 want old_platform err
  [ "${1:-}" = "--prompt" ] && force=1
  info "Finding app targets (bazel query)..."
  err="$STATE/query.err"
  out="$(bazel_cmd query --keep_going --noshow_progress "$APP_KINDS" --output=label_kind 2>"$err")" || true
  local labels=() kinds=()
  while read -r kind rule label; do
    [ "$rule" = rule ] && [ -n "$label" ] && { labels+=("$label"); kinds+=("$kind"); }
  done <<< "$out"
  [ ${#labels[@]} -gt 0 ] || die "No ios_application/macos_application/... targets found. bazel said: $(tail -n 15 "$err")"
  want="${XC_PREF_TARGET:-$XC_BAZEL_TARGET}"
  if [ -n "$want" ]; then
    case "$want" in //*|@*) ;; *) want="//$want" ;; esac
    for i in "${!labels[@]}"; do
      if [ "${labels[$i]}" = "$want" ] || [ "${labels[$i]}" = "$want:${want##*/}" ]; then def=$i; found=1; fi
    done
    [ "$found" = 1 ] || warn "Bazel target '$want' not found (or it isn't an *_application)."
  fi
  if [ ${#labels[@]} -gt 1 ] && interactive && { [ "$force" = 1 ] || [ "$found" = 0 ]; }; then
    local items=()
    for i in "${!labels[@]}"; do items+=("${labels[$i]}  (${kinds[$i]})"); done
    choose "$def" "Which app should VS Code build?" "${items[@]}"
    def=$CHOICE
  fi
  XC_BAZEL_TARGET="${labels[$def]}"
  old_platform="$XC_PLATFORM"
  XC_PLATFORM="${kinds[$def]%%_*}"
  ok "Bazel target: $XC_BAZEL_TARGET (${kinds[$def]})"
  [ "$old_platform" = "$XC_PLATFORM" ] || { XC_SIM_UDID=""; XC_SIM_NAME=""; }
  save_config
  if is_sim && [ -z "$XC_SIM_UDID" ]; then cmd_select_sim; fi
  bazel_refresh_index
}

# Code completion for Bazel: Spotify's sourcekit-bazel-bsp, a build server SourceKit-LSP talks to.
# This does what its `setup_sourcekit_bsp` Bazel rule does, without editing MODULE.bazel or BUILD files:
# it fetches a pinned release and writes .bsp/skbsp.json, .bsp/sourcekit-bazel-bsp and .sourcekit-lsp/config.json.
SKBSP_VERSION="0.8.3"
PY_SKBSP='
import json, sys
tpl_bsp, out_bsp, out_lsp, bazel, target, files = sys.argv[1:7]
flags = sys.argv[7:]
argv = [".bsp/sourcekit-bazel-bsp", "serve", "--target", target, "--bazel-wrapper", bazel, "--compile-top-level"]
for f in flags:
    argv += ["--index-flag", f[2:] if f.startswith("--") else f]
argv += ["--files-to-watch", files]
with open(tpl_bsp) as f:
    tpl = f.read()
with open(out_bsp, "w") as f:
    f.write(tpl.replace("%argv%", ",\n        ".join(json.dumps(a) for a in argv)))
lsp = {
    "backgroundIndexing": True,
    "backgroundPreparationMode": "build",
    "defaultWorkspaceType": "buildServer",
    "index": {"indexPrefixMap": {
        "./OUTPUT_PATH_NAME_PLACEHOLDER": "OUTPUT_PATH_PLACEHOLDER",
        "../OUTPUT_PATH_NAME_PLACEHOLDER": "OUTPUT_PATH_PLACEHOLDER",
        "./external": "EXTERNAL_ROOT_PLACEHOLDER",
        ".": "EXECUTION_ROOT_PLACEHOLDER",
    }},
}
with open(out_lsp, "w") as f:
    json.dump(lsp, f, indent=2)
'

bazel_refresh_index() {
  [ -n "$XC_BAZEL_TARGET" ] || die "No Bazel target selected."
  local ver="$SKBSP_VERSION" cache="$STATE/skbsp-$SKBSP_VERSION" mark="$ROOT/.bsp/.vscode-xcode-setup"
  local base="https://github.com/spotify/sourcekit-bazel-bsp/releases/download/$ver" bin tpl tpl_bsp script
  if [ -f "$ROOT/.bsp/skbsp.json" ] && [ ! -f "$mark" ]; then
    ok "Code completion: .bsp/skbsp.json is already set up by your project (setup_sourcekit_bsp); leaving it as is."
    return 0
  fi
  if [ ! -f "$cache/ok" ]; then
    info "Downloading sourcekit-bazel-bsp $ver (Bazel build server for code completion)..."
    rm -rf "$cache"; mkdir -p "$cache/bin" "$cache/src"
    if ! { curl -fsSL -o "$cache/bin.zip" "$base/sourcekit-bazel-bsp-$ver-darwin.zip" \
          && curl -fsSL -o "$cache/src.tar.gz" "$base/release.tar.gz" \
          && unzip -q -o "$cache/bin.zip" -d "$cache/bin" && tar -xzf "$cache/src.tar.gz" -C "$cache/src"; }; then
      warn "Couldn't download sourcekit-bazel-bsp; code completion won't know about Bazel targets. Retry with 'Xcode: Refresh Code Completion'."
      return 0
    fi
    touch "$cache/ok"
  fi
  bin="$(find "$cache/bin" -name sourcekit-bazel-bsp -type f | head -n 1)"
  tpl="$(find "$cache/src" -name setup_sourcekit_bsp.sh.tpl | head -n 1)"
  tpl_bsp="$(find "$cache/src" -name bsp_config.json.tpl | head -n 1)"
  if [ -z "$bin" ] || [ -z "$tpl" ] || [ -z "$tpl_bsp" ]; then
    warn "The sourcekit-bazel-bsp $ver download looks different than expected; skipping code completion setup."
    return 0
  fi
  chmod +x "$bin"
  bazel_flags
  python3 -I -c "$PY_SKBSP" "$tpl_bsp" "$cache/skbsp.json" "$cache/config.json" "$(bazel_bin)" "$XC_BAZEL_TARGET" \
    "**/*.swift,**/*.h,**/*.m,**/*.mm,**/*.c,**/*.cpp" "${BFLAGS[@]}" \
    --features=swift.index_while_building --experimental_convenience_symlinks=ignore --color=no --curses=no \
    || { warn "Couldn't write the sourcekit-bazel-bsp config."; return 0; }
  script="$cache/setup.sh"
  sed -e "s|%sourcekit_bazel_bsp_path%|$bin|g" -e "s|%bsp_config_path%|$cache/skbsp.json|g" \
      -e "s|%lsp_config_path%|$cache/config.json|g" -e "s|%merge_lsp_config_env%|1|g" \
      -e "s|%bazel_wrapper%|$(bazel_bin)|g" -e "s|%no_extra_output_base_env%||g" "$tpl" > "$script"
  if BUILD_WORKSPACE_DIRECTORY="$ROOT" /bin/bash "$script" > "$STATE/skbsp-setup.log" 2>&1; then
    touch "$mark"
    ok "Code completion set up for $XC_BAZEL_TARGET (sourcekit-bazel-bsp). Run 'Swift: Restart LSP Server' if VS Code was already open."
  else
    warn "sourcekit-bazel-bsp setup failed; see $STATE/skbsp-setup.log"
  fi
}

# LLDB settings for Bazel-built code: rules_swift/apple_support write workspace-relative paths into
# debug info (-debug-prefix-map PWD=.), so map them back to this folder (and external repos).
bazel_lldb_settings() {
  bazel_info
  printf 'platform settings -w "%s"\n' "$BZ_EXECROOT"
  printf 'settings set target.source-map ./external "%s/external" . "%s"\n' "$BZ_OUTPUT_BASE" "$ROOT"
}

cmd="${1:-help}"
[ $# -gt 0 ] && shift
case "$cmd" in
  build) cmd_build ;;
  run) cmd_run ;;
  test) cmd_test ;;
  clean) cmd_clean ;;
  debug-prepare) cmd_debug_prepare ;;
  stop) cmd_stop ;;
  logs) tail -n +1 -f "$STATE/console.log" ;;
  select-scheme) cmd_select_scheme "$@" ;;
  select-sim) cmd_select_sim "$@" ;;
  refresh-index) cmd_refresh_index ;;
  open-sim) build_args; is_sim && boot_sim ;;
  info) cmd_info ;;
  help|-h|--help) sed -n '2,18p' "$0" | sed 's/^# \{0,1\}//' ;;
  *) die "Unknown command '$cmd'. Run: $0 help" ;;
esac
